# 046 - devocalizza per gli abbonati

import sys


def traccia(testo):
    riga = '[046] %s' % testo
    try:
        print(riga)
    except Exception:
        pass
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch046.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s%s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                riga, chr(10)))
    except Exception:
        pass


CODICE_LIC = 'def _kdm_bool(v):\n    """Normalizza un valore kdm a \'1\'/\'0\'."""\n    return \'1\' if str(v).strip() in (\'1\', \'True\', \'true\', \'yes\') else \'0\'\n\n\ndef _set_devoc(devoc):\n    """Persiste lo stato dell\'abbonamento Devocalizza. Assente = non abbonato."""\n    if not isinstance(devoc, dict):\n        devoc = {}\n    sc = devoc.get(\'scadenza\')\n    sc = \'\' if sc is None else str(sc).strip()[:10]\n    try:\n        from .database import Database\n        Database.set_config(\'devoc_attivo\', _kdm_bool(devoc.get(\'attivo\', 0)))\n        Database.set_config(\'devoc_scadenza\', sc)\n    except Exception:\n        pass\n\n\ndef devoc_abilitato():\n    """True se il cliente e\' abbonato a Devocalizza e l\'abbonamento non e\'\n    scaduto (grazia offline fino alla scadenza)."""\n    try:\n        from .database import Database\n        if Database.get_config(\'devoc_attivo\', \'0\') != \'1\':\n            return False\n        sc = (Database.get_config(\'devoc_scadenza\', \'\') or \'\').strip()\n    except Exception:\n        return False\n    if not sc:\n        return True\n    try:\n        from datetime import date\n        y, m, d = sc.split(\'-\')\n        return date(int(y), int(m), int(d)) >= date.today()\n    except Exception:\n        return True\n\n\n'

CODICE_VER = 'def verify_license_remote(nome, cognome, serial, license_key, timeout=12):\n    """Verifica la licenza tramite l\'API SERVER (le credenziali DB stanno SOLO\n    sul server, non piu\' nel client). Mantiene il backfill hw_id/pc_name: il\n    client calcola il proprio fingerprint e lo invia, il server popola i campi\n    mancanti come prima.\n\n    Ritorna:\n      - dict {\'valid\': True, \'edition\': \'pro\'|\'home\'}  licenza valida\n      - False  licenza NON valida (non trovata, revocata, ...)\n      - None   errore di connessione/risposta (NON blocca l\'avvio)\n    """\n    try:\n        import urllib.request\n\n        # Fingerprint del PC per il backfill lato server (come la vecchia logica)\n        try:\n            cpu_id, mb_id = get_hardware_id()\n            hw_id, pc_name = _get_pc_fingerprint(cpu_id, mb_id)\n        except Exception:\n            hw_id, pc_name = \'\', \'\'\n\n        payload = json.dumps({\n            \'nome\': nome, \'cognome\': cognome, \'serial\': serial,\n            \'license_key\': license_key, \'hw_id\': hw_id, \'pc_name\': pc_name,\n        }).encode(\'utf-8\')\n\n        req = urllib.request.Request(\n            LICENSE_API_URL, data=payload,\n            headers={\'Content-Type\': \'application/json\'}, method=\'POST\')\n        with urllib.request.urlopen(req, timeout=timeout) as resp:\n            data = json.loads(resp.read().decode(\'utf-8\'))\n\n        if data.get(\'valid\') is True:\n            ed = (data.get(\'edition\') or \'pro\').lower().strip()\n            if ed not in (\'pro\', \'home\'):\n                ed = \'pro\'\n            # ✅ KDM (database online basi mp3/video): leggi e persisti i flag.\n            #    Campo assente = retrocompat -> tutto disabilitato.\n            _set_kdm(data.get(\'kdm\'))\n            # ✅ Abbonamento Devocalizza: il tasto compare solo a chi e\' abbonato.\n            #    Campo assente (server vecchio) = non abbonato.\n            _set_devoc(data.get(\'devoc\'))\n            return {\'valid\': True, \'edition\': ed,\n                    \'richieste\': int(data.get(\'richieste\') or 0),\n                    \'sig\': data.get(\'sig\') or \'\'}\n        elif data.get(\'valid\') is False:\n            # Memorizza il MOTIVO (se il server lo dice): serve per decidere se la\n            # licenza va DISTRUTTA (revoca vera) o solo bloccata per questa sessione.\n            global _LAST_REMOTE_REASON\n            _LAST_REMOTE_REASON = str(\n                data.get(\'reason\') or data.get(\'status\') or data.get(\'motivo\') or \'\').lower().strip()\n            return False\n        else:\n            # risposta inattesa ({\'error\':...}) -> trattala come errore, non blocca\n            return None\n\n    except Exception as e:\n        print(f"Errore verifica licenza (API): {e}")\n        return None\n\n\n'

CODICE_DEVOC = '# -*- coding: utf-8 -*-\n"""\ndevocalizza.py — toglie (o abbassa) la voce da un brano, sul PC del cliente.\n\nCOME FUNZIONA\n    Usa un modello MDX-Net, lo stesso che sta dentro Ultimate Vocal Remover.\n    Lavora sullo spettro: il suono viene scomposto in 3072 bande, il modello\n    dice quali parti sono musica, e quello che resta e\' la voce.\n\n    Il modello gira con onnxruntime SUL PROCESSORE: non serve una scheda\n    video, e nemmeno la connessione dopo la prima volta.\n\nCOSA SERVE, E COME SE LO PROCURA\n    - onnxruntime  (~14 MB, da PyPI)   in dipendenze/devocalizza/\n    - il modello   (~64 MB, da GitHub) in dipendenze/devocalizza/\n    Si scaricano DA SOLI al primo uso, come gia\' succede per yt-dlp e deno:\n    il cliente non deve installare niente a mano. Chi non preme il bottone\n    non scarica nulla.\n\n⚠️ NON TOGLIE LA VOCE PERFETTAMENTE, e non e\' un difetto: e\' un modello\n   veloce, scelto per girare su qualunque PC. Lasciando dentro un po\' di voce\n   originale (`quanto_voce`) i difetti si sentono molto meno - ed e\' anche\n   quello che serve dal vivo, dove la voce guida aiuta chi canta.\n"""\n\nimport os\nimport subprocess\nimport sys\nimport threading\nimport urllib.request\n\n# --- DUE MODI, e cambiano il risultato per chi canta:\n#\n#     "tutta"  toglie TUTTA la voce, cori compresi.\n#     "cori"   toglie SOLO chi canta davanti e LASCIA I CORI nella base —\n#              e i cori nella base sono un miglioramento gia\' misurato su 14\n#              brani in questo progetto, non un\'opinione.\n#\n# ⚠️ I due modelli NON hanno le stesse misure: il primo lavora su 3072 bande,\n#    il secondo su 2048, e la finestra da cui vengono e\' diversa. Sbagliarla\n#    non da\' errore: il modello risponde lo stesso e separa male. Il valore\n#    del secondo (5120) e\' stato TROVATO PROVANDO, non copiato.\n#\n# ⚠️ `esce`: cosa restituisce il modello. I modelli "Inst" danno LA BASE, i\n#    modelli "Voc" danno LA VOCE — e la base si ricava per differenza. Non e\'\n#    scritto da nessuna parte nel file .onnx: si vede provando. MISURATO:\n#    usando un modello della voce come se desse la base si porta via il 99%\n#    della musica (-44 dB), cioe\' resta quasi il silenzio.\nMODELLI = {\n    \'tutta\': dict(file="UVR-MDX-NET-Inst_HQ_3.onnx",\n                  n_fft=6144, dim_f=3072, dim_t=256, hop=1024, esce=\'base\'),\n    \'cori\':  dict(file="UVR_MDXNET_KARA_2.onnx",\n                  n_fft=5120, dim_f=2048, dim_t=256, hop=1024, esce=\'base\'),\n    # ⭐ IL MIGLIORE PER TOGLIERE LA VOCE: mel_band_roformer_karaoke (aufr33 e\n    #    viperx), a 8 bit. L\'utente l\'ha ascoltato contro quello normale:\n    #    "sembrerebbe apposto". Gira in un MOTORE A PARTE (vedi\n    #    `_MotoreRoformer`), perche\' ha bisogno di PyTorch e il programma\n    #    compilato PyTorch non ce l\'ha — apposta, per non pesare 300 MB.\n    # ⚠️ MISURATO su i7-11800H: 0,75x il tempo reale. Non basta per partire\n    #    SUBITO, ma basta partire POCO DOPO: un brano di 4 minuti si puo\'\n    #    mandare dopo circa 1 minuto e 20 (vedi `_voce_separa_avanti`).\n    # ⛔ onnxruntime NON va: la stessa rete in ONNX a 8 bit fa 0,44x, e con\n    #    le ottimizzazioni piene si rompe su /band_split/Split.\n    \'roformer\': dict(file="roformer_karaoke_int8.pt", tipo=\'roformer\',\n                     n_fft=2048, dim_f=1025, dim_t=801, hop=441, esce=\'voce\'),\n}\n\n# --- il motore del roformer: pezzi da 8 s ESATTI (la rete e\' tracciata\n#     cosi\'), di cui 0,25 s per parte sono solo contesto: senza, il modello\n#     non sa cosa c\'e\' prima e dopo e sbaglia proprio sui bordi del pezzo.\nRF_N = 352800\nRF_CTX = 11025\nTIPO = \'mdx\'\n# ⭐ LA CODA: il roformer restituisce anche 46 ms OLTRE la fine del pezzo\n#    (li ha gia\' calcolati, sono nel contesto). Chi scrive il brano li mette\n#    giu\', e il pezzo dopo sfuma partendo da LORO invece che dal ripiego del\n#    filtro. Senza, a ogni giunta (ogni 7,5 s) la sfumatura passava per il\n#    filtro — che e\' piu\' vuoto — e si sentiva un piccolo calo: le\n#    "depressioni".\nCODA = 0\n\n\ndef _modelli_in_piu():\n    """Modelli aggiunti a mano, senza toccare il programma.\n\n    ⭐ Basta mettere il file .onnx in `dipendenze/devocalizza/` e descriverlo\n       in `modelli.json`, nella stessa cartella:\n\n           {\n             "kim": {"file": "Kim_Vocal_2.onnx", "n_fft": 7680,\n                     "dim_f": 3072, "dim_t": 256, "hop": 1024,\n                     "esce": "voce"}\n           }\n\n    ⚠️ `dim_f` e `dim_t` NON si indovinano: si leggono dal modello stesso\n       (l\'ingresso e\' (1, 4, dim_f, dim_t)). `n_fft` invece va provato: se e\'\n       sbagliato il modello NON da\' errore, risponde lo stesso e separa male.\n    """\n    import json\n    try:\n        p = os.path.join(cartella(), \'modelli.json\')\n        if not os.path.exists(p):\n            return {}\n        with open(p, encoding=\'utf-8\') as f:\n            dati = json.load(f)\n        buoni = {}\n        for nome, m in (dati or {}).items():\n            if not isinstance(m, dict) or not m.get(\'file\'):\n                continue\n            buoni[str(nome)] = dict(\n                file=m[\'file\'],\n                n_fft=int(m.get(\'n_fft\', 6144)),\n                dim_f=int(m.get(\'dim_f\', 3072)),\n                dim_t=int(m.get(\'dim_t\', 256)),\n                hop=int(m.get(\'hop\', 1024)),\n                esce=\'voce\' if str(m.get(\'esce\', \'base\')) == \'voce\' else \'base\')\n        if buoni:\n            print("[devocalizza] modelli in piu\' da modelli.json: %s"\n                  % \', \'.join(sorted(buoni)))\n        return buoni\n    except Exception as e:\n        print("[devocalizza] modelli.json non letto: %s" % e)\n        return {}\n# ⭐ Si parte da \'tutta\': via TUTTA la voce, cori compresi.\n#\n# ⚠️ Prima era \'cori\', che lascia i cori nella base — e i cori nella base sono\n#    un miglioramento misurato su 14 brani in questo progetto. Ma dal vivo\n#    l\'utente ha scelto diversamente: con \'cori\' il solista si sente ancora in\n#    sottofondo, perche\' quel modello per costruzione lascia passare le voci\n#    allargate. Meglio rinunciare ai cori che avere il cantante originale\n#    sotto a quello vero.\n#    Chi la pensa al contrario mette \'cori\' in devoc_modo nelle impostazioni.\nPREDEFINITO = \'tutta\'\nBASE_URL = ("https://github.com/TRvlvr/model_repo/releases/download/"\n            "all_public_uvr_models/")\n\nSR = 44100\n\n# ⛔ Le misure si prendono TUTTE dallo stesso modo, mai una per una a mano:\n#    scriverle a mano significa, prima o poi, avere il nome di un modello e la\n#    finestra di un altro. E quell\'errore non si vede — il modello risponde\n#    lo stesso e separa male.\n_M = MODELLI[PREDEFINITO]\nN_FFT = _M[\'n_fft\']\nHOP = _M[\'hop\']\nDIM_F = _M[\'dim_f\']\nDIM_T = _M[\'dim_t\']\nCHUNK = HOP * (DIM_T - 1)\nMODELLO_NOME = _M[\'file\']\nMODELLO_URL = BASE_URL + MODELLO_NOME\nESCE = _M.get(\'esce\', \'base\')      # \'base\' oppure \'voce\'\n\n\ndef tutti_i_modelli():\n    """Quelli scritti qui piu\' quelli aggiunti in `modelli.json`.\n\n    Chi sta in modelli.json VINCE sullo stesso nome: cosi\' si puo\' correggere\n    la finestra di un modello senza toccare il programma.\n    """\n    fuori = dict(MODELLI)\n    fuori.update(_modelli_in_piu())\n    return fuori\n\n\ndef _usa(modo):\n    """Imposta le misure del modo scelto. Da chiamare PRIMA di separare."""\n    global N_FFT, HOP, DIM_F, DIM_T, CHUNK, MODELLO_NOME, MODELLO_URL, ESCE, TIPO\n    global CODA\n    elenco = tutti_i_modelli()\n    m = elenco.get(modo or PREDEFINITO) or elenco[PREDEFINITO]\n    N_FFT, HOP, DIM_F, DIM_T = m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'], m[\'dim_t\']\n    CHUNK = HOP * (DIM_T - 1)\n    ESCE = m.get(\'esce\', \'base\')\n    TIPO = m.get(\'tipo\', \'mdx\')\n    CODA = 0\n    if TIPO == \'roformer\':\n        CHUNK = RF_N - 2 * RF_CTX           # la parte utile del pezzo\n        CODA = 2048\n    if MODELLO_NOME != m[\'file\']:\n        _sessione[0] = None            # cambia modello: si riapre\n    MODELLO_NOME = m[\'file\']\n    MODELLO_URL = BASE_URL + MODELLO_NOME\n    return m\n# la ruota di onnxruntime per la versione di Python con cui e\' fatto il\n# programma: deve combaciare, altrimenti non si carica\nONNX_URL = ("https://files.pythonhosted.org/packages/source-independent/"\n            "onnxruntime-1.29.0-cp313-cp313-win_amd64.whl")\nONNX_PYPI = "https://pypi.org/pypi/onnxruntime/json"\n\n_lucchetto = threading.Lock()\n_sessione = [None]\n\n\n# --------------------------------------------------------------- le cartelle\ndef _base():\n    """La cartella del programma, sia da sorgente sia compilato."""\n    if getattr(sys, \'frozen\', False) or (\'__compiled__\' in globals()):\n        return os.path.dirname(os.path.abspath(sys.argv[0]))\n    return os.path.abspath(os.path.join(os.path.dirname(__file__), \'..\'))\n\n\ndef cartella():\n    d = os.path.join(_base(), \'dipendenze\', \'devocalizza\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        # in Program Files potrebbe non essere scrivibile: si ripiega\n        # nella cartella dell\'utente, dove i permessi ci sono sempre\n        d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or\n                         os.path.expanduser(\'~\'), \'KaraDom\', \'devocalizza\')\n        os.makedirs(d, exist_ok=True)\n    return d\n\n\ndef _ffmpeg():\n    for c in (os.path.join(_base(), \'dipendenze\', \'ffmpeg.exe\'),\n              os.path.join(_base(), \'ffmpeg.exe\'),\n              \'ffmpeg\'):\n        if c == \'ffmpeg\' or os.path.exists(c):\n            return c\n    return \'ffmpeg\'\n\n\n# ------------------------------------------------------- procurarsi il pezzo\ndef _scarica(url, dove, avviso=None):\n    """Scarica dicendo a che punto e\', e NON lascia mai un file a meta\':\n    si scrive in un file temporaneo e si rinomina solo alla fine."""\n    tmp = dove + \'.parte\'\n    req = urllib.request.Request(url, headers={\'User-Agent\': \'KaraDom\'})\n    with urllib.request.urlopen(req, timeout=60) as r:\n        totale = int(r.headers.get(\'Content-Length\') or 0)\n        fatto = 0\n        with open(tmp, \'wb\') as f:\n            while True:\n                pezzo = r.read(262144)\n                if not pezzo:\n                    break\n                f.write(pezzo)\n                fatto += len(pezzo)\n                if avviso and totale:\n                    avviso(fatto * 100 // totale)\n    os.replace(tmp, dove)\n    return dove\n\n\ndef _onnx_wheel_url():\n    """L\'indirizzo vero della ruota giusta, chiesto a PyPI.\n\n    Non si scrive a mano: gli indirizzi dei pacchetti cambiano a ogni\n    versione, e uno sbagliato darebbe un 404 al primo cliente che prova.\n    """\n    import json\n    tag = \'cp%d%d\' % (sys.version_info[0], sys.version_info[1])\n    with urllib.request.urlopen(ONNX_PYPI, timeout=30) as r:\n        dati = json.loads(r.read().decode(\'utf-8\'))\n    for versione in sorted(dati.get(\'releases\', {}), reverse=True):\n        for file in dati[\'releases\'][versione]:\n            n = file.get(\'filename\', \'\')\n            if tag in n and \'win_amd64\' in n and n.endswith(\'.whl\'):\n                return file[\'url\'], n\n    raise RuntimeError("nessuna versione di onnxruntime per Python %s"\n                       % \'.\'.join(map(str, sys.version_info[:2])))\n\n\ndef procura_onnxruntime(avviso=None):\n    """Ritorna il modulo onnxruntime, scaricandolo se non c\'e\'."""\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    d = cartella()\n    if d not in sys.path:\n        sys.path.insert(0, d)\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    if avviso:\n        avviso(0, "Scarico il motore (una volta sola, ~14 MB)…")\n    url, nome = _onnx_wheel_url()\n    whl = os.path.join(d, nome)\n    if not os.path.exists(whl):\n        _scarica(url, whl, (lambda p: avviso(p, "Motore… %d%%" % p)) if avviso else None)\n    # la ruota e\' uno zip: si scompatta qui dentro e basta\n    import zipfile\n    with zipfile.ZipFile(whl) as z:\n        z.extractall(d)\n    try:\n        os.remove(whl)\n    except Exception:\n        pass\n    import onnxruntime\n    return onnxruntime\n\n\ndef procura_modello(avviso=None):\n    d = cartella()\n    f = os.path.join(d, MODELLO_NOME)\n    if not os.path.exists(f):\n        if avviso:\n            avviso(0, "Scarico il modello (una volta sola, ~64 MB)…")\n        _scarica(MODELLO_URL, f,\n                 (lambda p: avviso(p, "Modello… %d%%" % p)) if avviso else None)\n    return f\n\n\ndef pronto():\n    """True se non c\'e\' niente da scaricare."""\n    if TIPO == \'roformer\':\n        return roformer_disponibile()\n    try:\n        import onnxruntime  # noqa: F401\n        motore = True\n    except Exception:\n        motore = os.path.isdir(os.path.join(cartella(), \'onnxruntime\'))\n    return motore and os.path.exists(os.path.join(cartella(), MODELLO_NOME))\n\n\n# ------------------------------------------------ il motore del roformer\n# ⭐ Gira in un PROCESSO A PARTE, con un Python che ha PyTorch. Il programma\n#    gli passa un pezzo da 8 s, lui risponde con la VOCE di quel pezzo.\n#    Cosi\':\n#      - il programma compilato resta com\'e\' (PyTorch e\' escluso apposta\n#        dalla build: 300 MB in piu\' per tutti, anche per chi non lo usa);\n#      - se il motore si pianta, il programma non se ne accorge nemmeno;\n#      - gira a priorita\' BASSA: la musica e il video che stanno suonando\n#        vengono prima di lui, e non si sentono scatti.\n# ⚠️ Il testo qui sotto e\' il motore stesso: si riscrive su disco a ogni\n#    avvio, cosi\' una patch lo aggiorna senza scaricare niente.\nMOTORE_PY = r\'\'\'# -*- coding: utf-8 -*-\n# Motore del roformer per KaraDom: lo avvia il programma, non va lanciato a mano.\nimport struct\nimport sys\n\nimport torch\n\nN = 352800\nNFFT = 2048\nHOP = 441\n\ntorch.set_num_threads(max(1, int(sys.argv[2])))\nrete = torch.jit.load(sys.argv[1], map_location="cpu").eval()\nfin = torch.hann_window(NFFT)\ningresso = sys.stdin.buffer\nuscita = sys.stdout.buffer\n\n\ndef leggi(quanti):\n    b = bytearray()\n    while len(b) < quanti:\n        p = ingresso.read(quanti - len(b))\n        if not p:\n            return None\n        b += p\n    return b\n\n\ndef voce_di(x):\n    """x: (2, N) -> la voce, (2, N)."""\n    S = torch.stft(x, n_fft=NFFT, hop_length=HOP, win_length=NFFT, window=fin,\n                   center=True, normalized=False, return_complex=True)\n    S = torch.view_as_real(S)                       # (2, 1025, 801, 2)\n    frame = S.shape[2]\n    # la rete vuole frequenze e canali alternati: indice = frequenza*2 + canale\n    S = S.permute(1, 0, 2, 3).reshape(1, 2050, frame, 2)\n    y = rete(S)                                     # (1, 1, 2050, 801, 2)\n    y = y.reshape(1025, 2, frame, 2).permute(1, 0, 2, 3).contiguous()\n    return torch.istft(torch.view_as_complex(y), n_fft=NFFT, hop_length=HOP,\n                       win_length=NFFT, window=fin, center=True,\n                       normalized=False, length=N)\n\n\nwith torch.inference_mode():\n    voce_di(torch.zeros(2, N))                      # il primo giro scalda\n    uscita.write(b"PRONTO\\n")\n    uscita.flush()\n    while True:\n        h = leggi(4)\n        if h is None:\n            break\n        n = struct.unpack("<I", bytes(h))[0]\n        if n == 0:\n            break\n        dati = leggi(n * 8)\n        if dati is None:\n            break\n        x = torch.frombuffer(dati, dtype=torch.float32).view(2, n)\n        if n < N:\n            x = torch.nn.functional.pad(x, (0, N - n))\n        v = voce_di(x[:, :N].contiguous())[:, :n]\n        uscita.write(v.contiguous().numpy().astype("<f4").tobytes())\n        uscita.flush()\n\'\'\'\n\n_motore = [None]\n\n\ndef _cartelle_roformer():\n    """Dove puo\' stare il roformer.\n\n    ⛔⛔ NON SOLO `cartella()`. Dentro la patch questo modulo non ha un vero\n        `__file__` (e\' \'<patch_voce_devoc>\'), e `_base()` risponde con la\n        cartella SOPRA quella da cui e\' partito il programma: sul PC\n        dell\'utente `C:\\\\Program Files\\\\dipendenze\\\\devocalizza`, senza\n        "KaraDom". Il modello messo accanto agli altri, nella cartella del\n        programma, non veniva trovato, e SENZA DIRE NIENTE si tornava al\n        modello vecchio: la prima prova "col roformer" era col modello\n        vecchio. Adesso si guarda in tutti i posti sensati.\n    """\n    tutte = [cartella()]\n    try:\n        tutte.append(os.path.join(os.path.dirname(os.path.abspath(sys.executable)),\n                                  \'dipendenze\', \'devocalizza\'))\n    except Exception:\n        pass\n    tutte.append(_cartella_utente())\n    visti, fuori = set(), []\n    for d in tutte:\n        k = os.path.abspath(d).lower()\n        if k not in visti:\n            visti.add(k)\n            fuori.append(d)\n    return fuori\n\n\ndef _cartella_utente():\n    """Quella dove si puo\' SEMPRE scrivere (Program Files spesso no)."""\n    d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or os.path.expanduser(\'~\'),\n                     \'KaraDom\', \'devocalizza\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        pass\n    return d\n\n\ndef _file_roformer():\n    for d in _cartelle_roformer():\n        f = os.path.join(d, MODELLI[\'roformer\'][\'file\'])\n        if os.path.exists(f):\n            return f\n    return None\n\n\ndef _python_motore():\n    """Il Python col PyTorch dentro. Prima quello scritto nelle impostazioni\n    (`devoc_python`), poi quello che si scarica accanto ai modelli."""\n    candidati = []\n    try:\n        from .database import Database\n        v = str(Database.get_config(\'devoc_python\', \'\')).strip()\n        if v:\n            candidati.append(v)\n    except Exception:\n        pass\n    for d in _cartelle_roformer():\n        candidati.append(os.path.join(d, \'motore\', \'python.exe\'))\n    for c in candidati:\n        if c and os.path.exists(c):\n            return c\n    return None\n\n\ndef roformer_disponibile():\n    """C\'e\' tutto per usare il roformer, senza scaricare niente?"""\n    return bool(_python_motore()) and bool(_file_roformer())\n\n\nclass _MotoreRoformer(object):\n    """Il processo del roformer. Un pezzo alla volta, in fila."""\n\n    def __init__(self, python, modello, thread):\n        import subprocess as sp\n        script = os.path.join(_cartella_utente(), \'roformer_motore.py\')\n        try:\n            vecchio = open(script, encoding=\'utf-8\').read()\n        except Exception:\n            vecchio = None\n        if vecchio != MOTORE_PY:\n            with open(script, \'w\', encoding=\'utf-8\', newline=\'\\n\') as f:\n                f.write(MOTORE_PY)\n        registro = open(os.path.join(_cartella_utente(), \'roformer_motore.log\'), \'ab\')\n        flag = 0\n        if os.name == \'nt\':\n            # niente finestra nera + priorita\' sotto il normale: chi suona\n            # viene prima di chi prepara\n            flag = 0x08000000 | 0x00004000\n        self.p = sp.Popen([python, \'-u\', script, modello, str(thread)],\n                          stdin=sp.PIPE, stdout=sp.PIPE, stderr=registro,\n                          creationflags=flag)\n        riga = self.p.stdout.readline()\n        if not riga.startswith(b\'PRONTO\'):\n            raise RuntimeError("il motore del roformer non e\' partito (%r) - "\n                               "vedi roformer_motore.log" % riga[:200])\n        self.lucchetto = threading.Lock()\n\n    def vivo(self):\n        return self.p.poll() is None\n\n    def voce(self, x):\n        """x: (2, n) con n <= RF_N -> la voce, (2, n)."""\n        import struct\n        import numpy as np\n        n = int(x.shape[1])\n        grezzo = np.ascontiguousarray(x, dtype=\'<f4\').tobytes()\n        with self.lucchetto:\n            self.p.stdin.write(struct.pack(\'<I\', n) + grezzo)\n            self.p.stdin.flush()\n            dati = bytearray()\n            while len(dati) < n * 8:\n                pezzo = self.p.stdout.read(n * 8 - len(dati))\n                if not pezzo:\n                    raise RuntimeError("il motore del roformer si e\' fermato")\n                dati += pezzo\n        return np.frombuffer(bytes(dati), dtype=\'<f4\').reshape(2, n)\n\n    def base(self, pezzo, mix=None, a=None):\n        """Il pezzo SENZA la voce, calcolato con 0,25 s di contesto per parte.\n\n        ⚠️ Il contesto si prende dal brano vero (`mix`, `a`) quando c\'e\':\n           cosi\' i bordi del pezzo il modello li vede come li sente chi\n           ascolta. Senza, si mette silenzio, che e\' meglio di niente.\n        """\n        import numpy as np\n        lung = pezzo.shape[1]\n        if mix is not None and a is not None:\n            tot = mix.shape[1]\n            da = int(a) - RF_CTX\n            fin = mix[:, max(0, da):max(0, min(tot, da + RF_N))]\n            sx = max(0, -da)\n            fin = np.pad(fin, ((0, 0), (sx, max(0, RF_N - sx - fin.shape[1]))))\n        else:\n            fin = np.pad(pezzo, ((0, 0), (RF_CTX, max(0, RF_N - RF_CTX - lung))))\n        v = self.voce(fin[:, :RF_N].astype(\'float32\'))\n        base = pezzo - v[:, RF_CTX:RF_CTX + lung]\n        # la CODA (vedi sopra): solo se il brano continua davvero.\n        # ⚠️ la misura e\' fissa QUI, non letta dal modulo: un altro lavoro che\n        #    apre il modello veloce la metterebbe a zero sotto i piedi\n        if mix is not None and a is not None:\n            coda = max(0, min(2048, mix.shape[1] - (int(a) + lung)))\n            if coda:\n                dopo = mix[:, int(a) + lung:int(a) + lung + coda]\n                base = np.concatenate(\n                    [base, dopo - v[:, RF_CTX + lung:RF_CTX + lung + coda]], axis=1)\n        return base\n\n\n_lucchetto_motore = threading.Lock()\n\n\ndef _motore_roformer(avviso=None):\n    # ⚠️ una serratura SUA: il motore impiega 12 s a partire, e con quella di\n    #    onnxruntime in quei 12 s si sarebbe fermato anche il modello veloce\n    #    che intanto pulisce la testa del brano\n    with _lucchetto_motore:\n        m = _motore[0]\n        if m is not None and m.vivo():\n            return m\n        py = _python_motore()\n        modello = _file_roformer()\n        if not py or not modello:\n            raise RuntimeError("il roformer non e\' su questo PC")\n        if avviso:\n            avviso(0, "Avvio il motore…")\n        _motore[0] = _MotoreRoformer(py, modello, quanti_thread())\n        return _motore[0]\n\n\n# --------------------------------------------------------------- lo spettro\ndef _finestra():\n    import numpy as np\n    # hann periodica, la stessa che usa il modello in addestramento\n    n = np.arange(N_FFT)\n    return (0.5 - 0.5 * np.cos(2.0 * np.pi * n / N_FFT)).astype(\'float32\')\n\n\ndef _stft(x, win, n_fft=None, hop=None, dim_f=None):\n    """x: (canali, campioni) -> (canali, DIM_F, frame) complesso.\n\n    Bordi riflessi, come `center=True`: senza, il primo e l\'ultimo pezzo di\n    ogni blocco perderebbero energia e si sentirebbero gli attacchi.\n\n    ⚠️ Le misure si possono passare: con due brani preparati insieme (uno\n       col roformer, uno col modello veloce) quelle del modulo cambiano\n       sotto i piedi. Vedi `_SessioneMDX`.\n    """\n    import numpy as np\n    N_FFT_, HOP_, DIM_F_ = n_fft or N_FFT, hop or HOP, dim_f or DIM_F\n    meta = N_FFT_ // 2\n    x = np.pad(x, ((0, 0), (meta, meta)), mode=\'reflect\')\n    frame = 1 + (x.shape[1] - N_FFT_) // HOP_\n    fuori = np.empty((x.shape[0], DIM_F_, frame), dtype=\'complex64\')\n    for i in range(frame):\n        pezzo = x[:, i * HOP_:i * HOP_ + N_FFT_] * win\n        fuori[:, :, i] = np.fft.rfft(pezzo, axis=1)[:, :DIM_F_]\n    return fuori\n\n\ndef _istft(S, win, campioni, n_fft=None, hop=None, dim_f=None):\n    """L\'inverso: si risomma con la finestra e si divide per quanto ogni\n    campione e\' stato coperto, se no dove le finestre si accavallano il\n    suono verrebbe piu\' forte."""\n    import numpy as np\n    N_FFT, HOP, DIM_F = (n_fft or globals()[\'N_FFT\'], hop or globals()[\'HOP\'],\n                         dim_f or globals()[\'DIM_F\'])\n    canali, _, frame = S.shape\n    meta = N_FFT // 2\n    lungo = (frame - 1) * HOP + N_FFT\n    fuori = np.zeros((canali, lungo), dtype=\'float32\')\n    pesi = np.zeros(lungo, dtype=\'float32\')\n    pieno = np.zeros((canali, N_FFT // 2 + 1), dtype=\'complex64\')\n    for i in range(frame):\n        pieno[:] = 0\n        pieno[:, :DIM_F] = S[:, :, i]\n        onda = np.fft.irfft(pieno, n=N_FFT, axis=1).astype(\'float32\')\n        fuori[:, i * HOP:i * HOP + N_FFT] += onda * win\n        pesi[i * HOP:i * HOP + N_FFT] += win * win\n    pesi[pesi < 1e-8] = 1e-8\n    fuori /= pesi\n    return fuori[:, meta:meta + campioni]\n\n\n# ------------------------------------------------------------- il lavoro vero\ndef _leggi_audio(percorso):\n    """Audio in stereo 44100 tramite ffmpeg: cosi\' legge tutto — mp3, mp4,\n    mkv, quello che c\'e\' — senza altre librerie."""\n    import numpy as np\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-i\', percorso,\n           \'-f\', \'f32le\', \'-acodec\', \'pcm_f32le\',\n           \'-ac\', \'2\', \'-ar\', str(SR), \'-\']\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000      # niente finestra nera\n    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0 or not p.stdout:\n        raise RuntimeError("ffmpeg non ha letto l\'audio: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    d = np.frombuffer(p.stdout, dtype=\'float32\').reshape(-1, 2).T.copy()\n    return d\n\n\ndef _scrivi_audio(dati, percorso):\n    import numpy as np\n    grezzo = np.ascontiguousarray(dati.T.astype(\'float32\')).tobytes()\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-y\',\n           \'-f\', \'f32le\', \'-ar\', str(SR), \'-ac\', \'2\', \'-i\', \'-\']\n    if percorso.lower().endswith(\'.mp3\'):\n        cmd += [\'-codec:a\', \'libmp3lame\', \'-b:a\', \'320k\']\n    cmd += [percorso]\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000\n    p = subprocess.run(cmd, input=grezzo, stdout=subprocess.PIPE,\n                       stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0:\n        raise RuntimeError("ffmpeg non ha scritto il file: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    return percorso\n\n\ndef quanti_thread(rimisura=False):\n    """Quanti core usare, MISURATO su questa macchina.\n\n    ⛔ Non si indovina: su 16 core usarli tutti e\' risultato il caso PEGGIORE\n       (2,06 s a blocco contro 1,67 con dodici, +19% di attesa) — oltre una\n       certa soglia i thread si ostacolano fra loro. Ma dove sia quella\n       soglia dipende dalla macchina, e una regola fissa andrebbe bene solo\n       sul computer su cui l\'ho scritta.\n\n    Quindi la prima volta si prova davvero: tre impostazioni, un blocco\n    ciascuna, si tiene la piu\' rapida e si ricorda. Costa pochi secondi, una\n    volta sola nella vita del programma.\n    """\n    n = max(1, os.cpu_count() or 4)\n    if not rimisura:\n        try:\n            from .database import Database\n            v = int(str(Database.get_config(\'devoc_thread\', \'0\')).strip())\n            if 1 <= v <= n:\n                return v\n        except Exception:\n            pass\n    # ripiego finche\' la misura non c\'e\': tre quarti dei core\n    return max(2, int(n * 0.75)) if n > 2 else n\n\n\ndef misura_thread(avviso=None):\n    """Prova le impostazioni su UN blocco e ricorda la migliore."""\n    import time\n    import numpy as np\n    import onnxruntime as ort\n\n    n = max(1, os.cpu_count() or 4)\n    candidati = sorted({max(2, n // 2), max(2, int(n * 0.75)), n} if n > 2 else {n})\n    modello = procura_modello(avviso)\n\n    # un blocco di rumore basta: si misura la macchina, non la musica\n    finto = np.random.randn(1, 4, DIM_F, DIM_T).astype(\'float32\') * 0.01\n    esiti = []\n    for th in candidati:\n        try:\n            o = ort.SessionOptions()\n            o.intra_op_num_threads = th\n            o.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n            s = ort.InferenceSession(modello, sess_options=o,\n                                     providers=[\'CPUExecutionProvider\'])\n            nome = s.get_inputs()[0].name\n            s.run(None, {nome: finto})          # il primo giro scalda\n            t0 = time.perf_counter()\n            s.run(None, {nome: finto})\n            esiti.append((time.perf_counter() - t0, th))\n            del s\n        except Exception:\n            continue\n    if not esiti:\n        return quanti_thread()\n    esiti.sort()\n    migliore = esiti[0][1]\n    try:\n        from .database import Database\n        Database.set_config(\'devoc_thread\', str(migliore))\n    except Exception:\n        pass\n    print("[devocalizza] misurato su questa macchina: %d core su %d "\n          "(%s)" % (migliore, n,\n                    ", ".join("%d=%.2fs" % (t2, t1) for t1, t2 in esiti)))\n    return migliore\n\n\ndef _sessione_onnx(avviso=None):\n    with _lucchetto:\n        if _sessione[0] is not None:\n            return _sessione[0]\n        ort = procura_onnxruntime(avviso)\n        modello = procura_modello(avviso)\n        # la prima volta si misura la macchina, poi il valore resta\n        try:\n            from .database import Database\n            if not str(Database.get_config(\'devoc_thread\', \'\')).strip():\n                if avviso:\n                    avviso(0, "Guardo quanto e\' veloce questo computer…")\n                misura_thread(avviso)\n        except Exception:\n            pass\n        opz = ort.SessionOptions()\n        opz.intra_op_num_threads = quanti_thread()\n        opz.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n        _sessione[0] = ort.InferenceSession(\n            modello, sess_options=opz, providers=[\'CPUExecutionProvider\'])\n        return _sessione[0]\n\n\ndef separa(percorso, avanzamento=None, modo=None):\n    """(base, voce) come due array (2, campioni). E\' il passo lento."""\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    if TIPO == \'roformer\':\n        motore = _motore_roformer(avanzamento)\n        mix = _leggi_audio(percorso)\n        totale = mix.shape[1]\n        base = np.zeros_like(mix)\n        quanti = max(1, (totale + CHUNK - 1) // CHUNK)\n        for n in range(quanti):\n            a = n * CHUNK\n            b = min(totale, a + CHUNK)\n            base[:, a:b] = motore.base(mix[:, a:b], mix, a)[:, :b - a]\n            if avanzamento:\n                avanzamento(int((n + 1) * 100 / quanti), "Separazione… %d%%"\n                            % int((n + 1) * 100 / quanti))\n        return base, mix - base\n    sess = _sessione_onnx(avanzamento)\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    base = np.zeros_like(mix)\n    quanti = max(1, (totale + CHUNK - 1) // CHUNK)\n    for n in range(quanti):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        if pezzo.shape[1] < CHUNK:            # l\'ultimo si allunga con silenzio\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - pezzo.shape[1])))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        # ⚠️ L\'ORDINE DEI QUATTRO PIANI CONTA: il modello li vuole alternati\n        #    per canale — sinistro reale, sinistro immaginario, destro reale,\n        #    destro immaginario. Mettendoli a blocchi (prima i due reali, poi\n        #    i due immaginari) il modello non riconosce piu\' niente e\n        #    restituisce quasi l\'ingresso: misurato, toglieva 0,6 dB invece\n        #    di separare.\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        onda = _istft(S2, win, CHUNK)\n        base[:, a:b] = onda[:, :b - a]\n        if avanzamento:\n            avanzamento(int((n + 1) * 100 / quanti), "Separazione… %d%%"\n                        % int((n + 1) * 100 / quanti))\n\n    voce = mix - base\n    return base, voce\n\n\ndef apri(modo=None, avviso=None):\n    """Prepara il modello e da\' gli attrezzi per lavorare UN pezzo alla volta.\n\n    Torna (sessione, finestra, CHUNK, SR). Serve a chi il giro dei pezzi se lo\n    fa per conto suo — per esempio chi sta riscrivendo un brano mentre suona e\n    deve decidere lui quando fermarsi e da dove ripartire.\n    """\n    with _lucchetto_misure:\n        _usa(modo)\n        tipo, chunk = TIPO, CHUNK\n        if tipo != \'roformer\':\n            # ⭐ la sessione si porta dietro le SUE misure (vedi `_SessioneMDX`)\n            mis = dict(n_fft=N_FFT, hop=HOP, dim_f=DIM_F, dim_t=DIM_T, esce=ESCE)\n            win = _finestra()\n            sess = _sessione_onnx(avviso)\n    if tipo == \'roformer\':\n        # ⚠️ fuori dalla serratura delle misure: il motore puo\' metterci 12 s\n        #    a partire, e intanto il modello veloce di un\'altra riga aspetterebbe\n        return _motore_roformer(avviso), None, chunk, SR\n    return _SessioneMDX(sess, mis), win, chunk, SR\n\n\n_lucchetto_misure = threading.Lock()\n\n\nclass _SessioneMDX(object):\n    """La sessione di onnxruntime INSIEME alle misure del suo modello.\n\n    ⛔⛔ Le misure (N_FFT, HOP, DIM_F, ...) sono variabili del modulo, e le\n        cambia chiunque apra un modello. Con due righe preparate insieme —\n        una col roformer, una col modello veloce — la seconda apertura\n        cambiava le misure alla prima mentre lavorava, e il modello\n        rispondeva lo stesso ma separava male, senza un errore.\n    """\n\n    def __init__(self, sess, mis):\n        self.sess = sess\n        self.mis = mis\n\n    def get_inputs(self):\n        return self.sess.get_inputs()\n\n    def run(self, *a, **k):\n        return self.sess.run(*a, **k)\n\n\ndef base_del_pezzo(sess, win, pezzo, mix=None, a=None):\n    """Il pezzo SENZA la voce. `pezzo`: (2, CHUNK) float32.\n\n    `mix` e `a` (il brano intero e dove comincia il pezzo) servono al\n    roformer per guardare un po\' prima e un po\' dopo; gli MDX li ignorano.\n\n    ⚠️ L\'ORDINE DEI QUATTRO PIANI CONTA: il modello li vuole alternati per\n       canale (sinistro reale, sinistro immaginario, destro reale, destro\n       immaginario). A blocchi non da\' errore: separa male e basta.\n    """\n    if isinstance(sess, _MotoreRoformer):\n        return sess.base(pezzo, mix, a)\n    import numpy as np\n    if isinstance(sess, _SessioneMDX):\n        m = sess.mis\n    else:\n        m = dict(n_fft=N_FFT, hop=HOP, dim_f=DIM_F, dim_t=DIM_T, esce=ESCE)\n    S = _stft(pezzo, win, m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'])[:, :, :m[\'dim_t\']]\n    x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                 axis=0).astype(\'float32\')[None]\n    y = sess.run(None, {sess.get_inputs()[0].name: x})[0][0]\n    S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n    uscita = _istft(S2, win, pezzo.shape[1], m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'])\n    # ⚠️ Qui esce SEMPRE la base, qualunque cosa produca il modello: chi\n    #    chiama non deve sapere se ha davanti un modello della base o della\n    #    voce. MISURATO: sbagliare questa riga porta via il 99% della musica.\n    if m[\'esce\'] == \'voce\':\n        return pezzo[:, :uscita.shape[1]] - uscita\n    return uscita\n\n\ndef separa_progressiva(percorso, quanto_voce=0.0, modo=None):\n    """Consegna il brano A PEZZI, appena sono pronti.\n\n    Serve per suonare mentre si separa: ogni giro restituisce\n    (secondo_di_inizio, audio_gia_devocalizzato). Il calcolo va a circa meta\'\n    della durata del brano, quindi ogni secondo speso ne produce due: con un\n    piccolo vantaggio iniziale il calcolo resta davanti a chi ascolta per\n    tutto il brano.\n\n    ⚠️ Il primo pezzo costa piu\' degli altri: la prima chiamata al modello\n    include l\'apertura del file e la preparazione, ed e\' il ritardo che\n    l\'ascoltatore sente prima di partire.\n    """\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    if TIPO == \'roformer\':\n        motore = _motore_roformer()\n        mix = _leggi_audio(percorso)\n        totale = mix.shape[1]\n        for n in range((totale + CHUNK - 1) // CHUNK):\n            a = n * CHUNK\n            b = min(totale, a + CHUNK)\n            base = motore.base(mix[:, a:b], mix, a)[:, :b - a]\n            if quanto_voce > 0:\n                base = base + (mix[:, a:b] - base) * float(quanto_voce)\n            yield a / float(SR), base\n        return\n    sess = _sessione_onnx()\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    for n in range((totale + CHUNK - 1) // CHUNK):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        vero = pezzo.shape[1]\n        if vero < CHUNK:\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - vero)))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        base = _istft(S2, win, CHUNK)[:, :vero]\n        if quanto_voce > 0:\n            base = base + (mix[:, a:b] - base) * float(quanto_voce)\n        yield a / float(SR), base\n\n\ndef quanto_abbassare():\n    """Di quanti decibel si abbassa la voce. Ritorna il FATTORE da usare.\n\n    ⛔ Non si TOGLIE la voce, si ABBASSA: il brano resta intero e la parte\n       riconosciuta come voce viene tirata giu\'. Cosi\' quello che il modello\n       sbaglia a riconoscere non resta a volume pieno - viene abbassato anche\n       lui - e non ci sono buchi nel suono.\n    """\n    db = 12.0\n    try:\n        from .database import Database\n        db = float(str(Database.get_config(\'devoc_db\', \'12\')).strip() or 12)\n    except Exception:\n        pass\n    db = max(0.0, min(60.0, db))\n    if db >= 60:\n        return 0.0                      # praticamente via del tutto\n    return 10.0 ** (-db / 20.0)         # -12 dB -> resta il 25%\n\n\ndef modo_scelto():\n    """Quale dei due modi ha scelto l\'utente nelle Opzioni (scheda Audio)."""\n    try:\n        from .database import Database\n        m = str(Database.get_config(\'devoc_modo\', PREDEFINITO)).strip()\n        if m in tutti_i_modelli():\n            # ⛔ il roformer ha bisogno del SUO motore: se su questo PC non\n            #    c\'e\', si torna al modello di sempre invece di non fare niente\n            if m == \'roformer\' and not roformer_disponibile():\n                return PREDEFINITO\n            return m\n    except Exception:\n        pass\n    return PREDEFINITO\n\n\ndef devocalizza(percorso, uscita=None, quanto_voce=None, avanzamento=None,\n                modo=None):\n    """Scrive il brano con la VOCE ABBASSATA.\n\n    quanto_voce: quanto ne resta. Se non lo si dice, si prende il livello\n    scelto nelle Opzioni (predefinito -12 dB, cioe\' ne resta un quarto).\n    modo: se non lo si dice, si usa quello scelto nelle Opzioni.\n    """\n    if quanto_voce is None:\n        quanto_voce = quanto_abbassare()\n    base, voce = separa(percorso, avanzamento, modo=modo or modo_scelto())\n    if quanto_voce > 0:\n        base = base + voce * float(quanto_voce)\n    # niente distorsione se la somma supera il fondo scala\n    import numpy as np\n    picco = float(np.max(np.abs(base))) if base.size else 0.0\n    if picco > 1.0:\n        base = base / picco\n    if not uscita:\n        radice, est = os.path.splitext(percorso)\n        uscita = radice + \' (devocalizzato)\' + (\'.mp3\' if est.lower() in\n                                                (\'.mp4\', \'.mkv\', \'.webm\', \'.avi\')\n                                                else est)\n    return _scrivi_audio(base, uscita)\n'

SERVONO = ('get_hardware_id', '_get_pc_fingerprint', 'LICENSE_API_URL', '_set_kdm')


def _licenza():
    m = sys.modules.get('moduli.licensing')
    if m is None:
        import moduli.licensing as m
    return m


def _devoc_si(self):
    return bool(getattr(self, '_devoc_ok', False))


def _togli_righe(self):
    cv = getattr(self, '_sc_cv', None)
    if cv is None:
        return
    for it in cv.find_withtag('btn'):
        if any(t.startswith('btn_voce_') for t in cv.gettags(it)):
            cv.delete(it)
    try:
        sx = max(cv.winfo_width(), 900) - self._S(65)
        for it in cv.find_all():
            if any(t.startswith('txt_ext_') for t in cv.gettags(it)):
                cv.coords(it, sx, cv.coords(it)[1])
    except Exception:
        pass


def _avvolgi_verifica(lic):
    vera = lic.verify_license_remote

    def verify_license_remote(nome, cognome, serial, license_key, *a, _vera=vera, **k):
        r = _vera(nome, cognome, serial, license_key, *a, **k)
        if isinstance(r, dict) and r.get('valid'):
            try:
                import json
                import urllib.request
                url = getattr(lic, 'LICENSE_API_URL',
                              'https://karadom.it/license/api/verify_license.php')
                corpo = json.dumps({'nome': nome, 'cognome': cognome, 'serial': serial,
                                    'license_key': license_key}).encode('utf-8')
                req = urllib.request.Request(url, data=corpo, method='POST',
                                             headers={'Content-Type': 'application/json'})
                with urllib.request.urlopen(req, timeout=6) as resp:
                    lic._set_devoc(json.loads(resp.read().decode('utf-8')).get('devoc'))
            except Exception as e:
                traccia('abbonamento non letto: %s' % e)
        return r

    verify_license_remote._s046 = True
    lic.verify_license_remote = verify_license_remote


def _avvolgi_ui(lic):
    fatte = 0
    for nome, mod in list(sys.modules.items()):
        if not nome.startswith('moduli.') or mod is None:
            continue
        for o in list(vars(mod).values()):
            if not isinstance(o, type):
                continue
            d = vars(o)
            f = d.get('create_slider')
            if f is not None and not getattr(f, '_s046', False):
                def create_slider(self, *a, _vera=f, **k):
                    r = _vera(self, *a, **k)
                    try:
                        self._devoc_ok = bool(lic.devoc_abilitato())
                        if not self._devoc_ok:
                            c = getattr(self, '_cornice_voce', None)
                            if c is not None:
                                c.pack_forget()
                            _togli_righe(self)
                    except Exception as e:
                        traccia('tasto in alto: %s' % e)
                    return r

                create_slider._s046 = True
                o.create_slider = create_slider
                fatte += 1
            for n in ('crea_riga', '_sc_redraw_all'):
                f = d.get(n)
                if f is None or getattr(f, '_s046', False):
                    continue

                def avvolta(self, *a, _vera=f, **k):
                    r = _vera(self, *a, **k)
                    try:
                        if not _devoc_si(self):
                            _togli_righe(self)
                    except Exception:
                        pass
                    return r

                avvolta._s046 = True
                avvolta.__name__ = n
                setattr(o, n, avvolta)
                fatte += 1
            if ('crea_riga' in d or 'create_slider' in d) and '_devoc_si' not in d:
                o._devoc_si = _devoc_si
    return fatte


def _modulo_voce():
    try:
        import types
        import moduli
        m = sys.modules.get('moduli.devocalizza')
        if m is None:
            m = types.ModuleType('moduli.devocalizza')
            m.__package__ = 'moduli'
            m.__file__ = '<patch046_devoc>'
        exec(compile(CODICE_DEVOC, '<patch046_devoc>', 'exec'), m.__dict__)
        sys.modules['moduli.devocalizza'] = m
        setattr(moduli, 'devocalizza', m)
        return True
    except Exception as e:
        traccia('modulo della voce NON messo: %s: %s' % (type(e).__name__, e))
        return False


def apply():
    try:
        lic = _licenza()
        gia = getattr(lic, 'devoc_abilitato', None)
        if gia is not None and not getattr(gia, '_s046', False):
            traccia('il programma lo fa gia da se')
            return True
        _modulo_voce()
        if gia is None:
            exec(compile(CODICE_LIC, '<patch046_lic>', 'exec'), lic.__dict__)
            lic._set_devoc._s046 = True
            lic.devoc_abilitato._s046 = True
            if all(hasattr(lic, n) for n in SERVONO):
                exec(compile(CODICE_VER, '<patch046_ver>', 'exec'), lic.__dict__)
                lic.verify_license_remote._s046 = True
                traccia('la verifica della licenza legge anche l-abbonamento')
            else:
                _avvolgi_verifica(lic)
                traccia('la verifica della licenza legge anche l-abbonamento (a parte)')
        n = _avvolgi_ui(lic)
        if n:
            traccia('tasto Devocalizza solo agli abbonati: %d punti agganciati' % n)
        return True
    except Exception as e:
        traccia('non agganciata: %s: %s' % (type(e).__name__, e))
        return False


def revert():
    return False


try:
    apply()
except Exception:
    pass
